# ---- Licence / registration checker + embeddable widget ----
_tx=lambda v:_h.unescape(re.sub(r'<[^>]+>','',v)).strip()
KEY={'scotland':['Licensing','Planning / control areas','Visitor levy'],'england':['Registration scheme','London 90-night rule','Business rates vs council tax','Overnight Visitor Levy'],'wales':['Registration (WRA)','Licensing','Visitor levy'],'northern-ireland':['Certification','Rates']}
HEAD={'scotland':('Yes: you need a licence.','Every short-term let in Scotland needs a licence from the council before you take bookings or guests.'),
'england':('No licence or registration yet.','England has no licensing or registration scheme in force. A national register is expected to begin in March 2027 (GOV.UK). In London, letting a whole home for more than 90 nights a year needs planning permission.'),
'wales':('Yes: you must register (free). No licence yet.','If you take bookings of 31 nights or fewer, you must register with the Welsh Revenue Authority by 31 March 2027. A licensing scheme is legislated but not in force.'),
'northern-ireland':('Yes: you need a Tourism NI certificate.','All visitor accommodation in Northern Ireland needs a current Tourism NI certificate after an inspection.')}
CD={'nations':[],'councils':[]}
for n in d['nations']:
    R={r['topic']:r for r in n['rules']}
    CD['nations'].append({'id':n['id'],'name':n['name'],'h':HEAD[n['id']][0],'s':HEAD[n['id']][1],'url':SITE+n['id']+'.html','rules':[{'t':t,'st':R[t]['status'],'x':R[t]['text'],'src':R[t]['sources']} for t in KEY[n['id']] if t in R]})
for c in d['councils']:
    s=slug(c)
    if s in CX and c['verified']:
        x=CX[s];CD['councils'].append({'n':c['name'],'nat':c['nation'],'url':SITE+'councils/'+s+'.html','sec':[[h,_tx(x[k][0]),x[k][1]] for h,k in (('Licensing or registration','lic'),('Planning','ctrl'),('Visitor levy','levy'),('Fees and council tax','fees')) if _tx(x[k][0])]})
CJ=json.dumps(CD,ensure_ascii=False).replace('</','<\\/')
CKF='''<form class="ckw" onsubmit="return false"><label for="ck-n">Nation</label><select id="ck-n"><option value="">Choose a nation</option></select><label for="ck-c">Council (optional)</label><select id="ck-c" disabled><option value="">All of the nation</option></select></form><div id="ck-out" aria-live="polite"></div>'''
CKJS='''<script>(function(){var D=%s,T=%s,N=document.getElementById('ck-n'),Cs=document.getElementById('ck-c'),O=document.getElementById('ck-out');
function el(t,x,c){var e=document.createElement(t);if(x)e.textContent=x;if(c)e.className=c;return e}
function lk(u,x){var a=el('a',x);a.href=u;a.rel='nofollow noopener';if(T)a.target='_blank';return a}
function srcs(L){var p=el('p','','small');p.appendChild(document.createTextNode(L.length?'Official source: ':'Official source: see the full page.'));L.forEach(function(u,i){if(i)p.appendChild(document.createTextNode(' · '));p.appendChild(lk(u,u.replace(/^https?:\\/\\/(www\\.)?/,'').split('/')[0]))});return p}
D.nations.forEach(function(n){var o=el('option',n.name);o.value=n.id;N.appendChild(o)});
function show(){O.innerHTML='';var n=D.nations.filter(function(x){return x.id===N.value})[0];if(!n)return;var c=D.councils.filter(function(x){return x.n===Cs.value})[0];
var b=el('div','','ck-res');b.appendChild(el('h2',n.h));b.appendChild(el('p',n.s));
if(c){b.appendChild(el('h3',c.n+': local rules'));c.sec.forEach(function(s){var d=el('div');d.appendChild(el('h4',s[0]));d.appendChild(el('p',s[1]));d.appendChild(srcs(s[2]));b.appendChild(d)})}
else{b.appendChild(el('h3','Key rules in '+n.name));n.rules.forEach(function(r){var d=el('div');d.appendChild(el('h4',r.t+' ('+r.st+')'));d.appendChild(el('p',r.x));d.appendChild(srcs(r.src));b.appendChild(d)})}
var f=el('p','','ck-more');f.appendChild(lk(c?c.url:n.url,'Full details at UK Short-Let Rules'));b.appendChild(f);
b.appendChild(el('p','General information only, not legal or tax advice. Always check the official source.','small'));O.appendChild(b)}
N.addEventListener('change',function(){Cs.innerHTML='';var a=el('option','All of the nation');a.value='';Cs.appendChild(a);var nm=(D.nations.filter(function(x){return x.id===N.value})[0]||{}).name;var L=D.councils.filter(function(x){return x.nat===nm});L.forEach(function(x){var o=el('option',x.n);o.value=x.n;Cs.appendChild(o)});Cs.disabled=!L.length;show()});
Cs.addEventListener('change',show);})();</script>'''
CKCSS='<style>.ckw{display:grid;gap:.4rem;max-width:28rem}.ckw select{padding:.6rem;font-size:1rem;width:100%%}.ck-res h4{margin:.8rem 0 .2rem}.ck-res p{margin:.2rem 0}.ck-more a{font-weight:700}</style>'
page('checker.html','Do I need a licence or registration for my short let?',f'<p class="lead">Pick a nation and, if we cover it, your council. You get the key licensing, registration, planning and levy rules, with links to the official sources.</p><div class="box">{CKF}</div>{CKJS % (CJ,"false")}<p>Covered councils: {len(CD["councils"])}. <a href="councils.html">See all council pages</a>. Want this checker on your own site? <a href="embed.html">Get the free embed code</a>.</p>',desc='Free checker: do you need a licence or registration for your UK short-term or holiday let? Pick your nation and council for the key rules, with official sources.',full_title='Short-let licence and registration checker (England, Scotland, Wales, NI) | UK Short-Let Rules Tracker',head=CKCSS.replace('%%','%'))
# Minimal widget page for iframes: no nav, no tracking, no third-party scripts
open('checker-widget.html','w').write(f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Short-let licence checker | UK Short-Let Rules</title><meta name="robots" content="noindex"><link rel="canonical" href="{SITE}checker.html"><style>body{{margin:0;padding:.8rem;font:15px/1.5 system-ui,sans-serif;color:#1d2433;background:#fff}}h1{{font-size:1.1rem;margin:0 0 .5rem}}h2{{font-size:1.05rem;margin:.8rem 0 .3rem}}h3{{font-size:1rem}}h4{{font-size:.95rem}}a{{color:#155a8a}}.small{{font-size:.8rem;color:#556}}.ckw label{{font-weight:600}}footer{{margin-top:.8rem;font-size:.8rem;color:#556}}</style>{CKCSS.replace('%%','%')}</head><body><main><h1>Do I need a licence or registration for my short let?</h1>{CKF}{CKJS % (CJ,"true")}</main><footer>Free checker by <a href="{SITE}" target="_blank" rel="noopener">UK Short-Let Rules</a>. Data last checked {C}.</footer></body></html>''')
SNIP=f'<iframe src="{SITE}checker-widget.html" title="UK short-let licence and registration checker" width="100%" height="620" style="border:1px solid #ccd;border-radius:8px;max-width:640px" loading="lazy"></iframe>\n<p style="font-size:13px">Checker by <a href="{SITE}">UK Short-Let Rules</a></p>'
page('embed.html','Add the free short-let licence checker to your site',f'''<p class="lead">Hosts, letting agents, property managers and bloggers can add our free checker to any website. Visitors pick a nation and council and see whether they need a licence or registration, with links to the official sources.</p>
<h2>Embed code</h2><p>Copy this and paste it into your page's HTML (in WordPress, use a "Custom HTML" block; in Squarespace or Wix, use an "Embed" or "Code" block):</p><textarea id="snip" rows="5" style="width:100%;font:13px monospace" readonly aria-label="Embed code">{e(SNIP)}</textarea><p><button type="button" id="cp">Copy code</button> <span id="cpm" class="small" aria-live="polite"></span></p>
<h2>What you get</h2><ul><li>Free to use, no sign-up and no API key.</li><li>No tracking, cookies, ads or third-party scripts. It loads one small page from our site.</li><li>Works on mobile, and with keyboards and screen readers (labelled form controls, live result area).</li><li>Updated automatically when we update our rules data. Every rule links to its official source.</li><li>Each result has a "Full details at UK Short-Let Rules" link to the matching nation or council page.</li></ul>
<h2>Tips</h2><ul><li>Change <code>height</code> if you need more room (results for some councils are long; the frame scrolls).</li><li>Please keep the credit link under the frame.</li><li>Prefer a plain link? Use <a href="checker.html">{SITE}checker.html</a>.</li></ul>
<h2>Preview</h2>{SNIP}
<p class="small">General information only, not legal or tax advice. Questions: <a href="mailto:hello@ukshortletrules.co.uk">hello@ukshortletrules.co.uk</a>. The UK Short-Let Rules team.</p>
<script>document.getElementById('cp').addEventListener('click',function(){{var t=document.getElementById('snip');t.select();var m=document.getElementById('cpm');(navigator.clipboard?navigator.clipboard.writeText(t.value):Promise.reject()).then(function(){{m.textContent='Copied.'}},function(){{document.execCommand('copy');m.textContent='Copied.'}})}});</script>''',desc='Free embeddable short-let licence and registration checker for UK hosts, letting agents and bloggers. One iframe, no tracking, official sources.',full_title='Embed the free UK short-let licence checker | UK Short-Let Rules Tracker')
